import{_ as i,o as e,c as t,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"CDS Jewel -- Cache Tiering","description":"","frontmatter":{"title":"CDS Jewel -- Cache Tiering","date":"2015-08-04T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph","缓存层优化","分布式存储","缓存驱逐算法","策略引擎"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_Cache_Tiering.md","filePath":"posts/2015/CDS_Jewel_--_Cache_Tiering.md","lastUpdated":1780459816000}'),a={name:"posts/2015/CDS_Jewel_--_Cache_Tiering.md"};function p(s,l,o,r,_,g){return e(),t("div",null,[...l[0]||(l[0]=[n("<p>在最近的Ceph分布式存储缓存层优化及策略讨论会议中，参与者们就缓存穿透问题、缓存驱逐算法优化和策略引擎开发等议题进行了深入讨论。</p><p><strong>一、缓存层优化</strong></p><ol><li><p><strong>缓存穿透问题</strong>：</p><ul><li>Sam提出了一个实验方案，通过仅在11%的情况下进行缓存更新，以测量缓存未命中成本。</li><li>该方案发现，对于复制池的随机读取，性能表现良好，因为之前较差的性能是由于不必要的更新消耗了缓存吞吐量。</li><li>建议通过更明确地跟踪最近的操作，并分配一些内存来跟踪最近的操作，从而专注于频繁访问的对象。</li></ul></li><li><p><strong>缓存驱逐算法优化</strong>：</p><ul><li>Alan和Anja King提出，当前的缓存驱逐算法基于对象年龄，导致驱逐决策不准确。</li><li>他们提出了以下改进方案： <ul><li>使用时间戳来计算对象的年龄，并持久化到磁盘。</li><li>使用重用距离算法，根据对象访问的频率和间隔来计算驱逐决策。</li><li>使用最近最少使用（LRU）列表和重用距离算法来优化驱逐决策。</li></ul></li></ul></li></ol><p><strong>二、策略引擎</strong></p><ul><li>Sandisk提出了一个策略引擎，用于管理缓存层策略，并支持用户定义的缓存策略，例如驱逐和提升调度。</li><li>策略引擎将与RGW通信，以确定要执行的策略，并通过HTTP头部将策略应用于对象。</li><li>策略引擎将支持基于对象、存储桶、池和全局的规则。</li></ul><p><strong>三、后续行动计划</strong></p><ol><li><p><strong>缓存穿透优化</strong>：</p><ul><li>Sam将根据讨论结果，进一步完善缓存穿透优化方案，并提交相关patch。</li></ul></li><li><p><strong>缓存驱逐算法优化</strong>：</p><ul><li>Alan和Anja King将根据讨论结果，选择合适的缓存驱逐算法优化方案，并提交相关patch。</li></ul></li><li><p><strong>策略引擎开发</strong>：</p><ul><li>Sandisk将根据讨论结果，进一步完善策略引擎设计方案，并提交相关patch。</li></ul></li><li><p><strong>持续讨论</strong>：</p><ul><li>与会人员将继续在邮件列表和IRC上进行讨论，并跟踪相关patch的进展。</li></ul></li></ol><p>通过本次会议，与会人员对Ceph分布式存储缓存层优化和策略引擎开发的相关问题进行了深入讨论，并提出了多个可行的解决方案。与会人员将根据讨论结果，进一步完善相关方案，并提交相关patch。</p>",8)])])}const d=i(a,[["render",p]]);export{u as __pageData,d as default};
